INSERT INTO `recipes` (`id`, `title`, `image`, `tags`, `type`, `time`, `rating`, `is_weekly_favorite`, `is_favorite`, `servings`, `calories`, `description`, `category_id`, `category_ids`, `ingredients`, `steps`, `chef_tips`, `is_draft`) VALUES ('1780047290823','Pollo en crema de cebollas caramelizadas','/uploads/24jp6jlsgfc_1780733279066.png','[\"Pollo\"]','standard','45-60 min',NULL,0,0,NULL,NULL,NULL,'1780743065787','[\"1780743065787\"]','[{\"cantidad\":\"4\",\"ingrediente\":\"muslos de pollo (o pechugas)\"},{\"cantidad\":\"2 unidades grandes\",\"ingrediente\":\"cebollas\"},{\"cantidad\":\"200 ml\",\"ingrediente\":\"crema de leche\"},{\"cantidad\":\"1 cucharada\",\"ingrediente\":\"miel o sirope sin azúcar\"},{\"cantidad\":\"2 dientes\",\"ingrediente\":\"ajo\"},{\"cantidad\":\"100 ml\",\"ingrediente\":\"caldo de pollo\"},{\"cantidad\":\"2 cucharadas\",\"ingrediente\":\"aceite de oliva\"},{\"cantidad\":\"Al gusto\",\"ingrediente\":\"sal\"},{\"cantidad\":\"Al gusto\",\"ingrediente\":\"pimienta negra\"},{\"cantidad\":\"1 cucharada picado\",\"ingrediente\":\"perejil fresco\"}]','[{\"step\":1,\"image_url\":null,\"description\":\"Salpimenta los muslos de pollo por ambos lados. Si utilizas pechugas, puedes cortarlas en filetes más pequeños para una cocción más rápida.\"},{\"step\":2,\"image_url\":null,\"description\":\"En una sartén grande, calienta una cucharada de aceite de oliva a fuego medio-bajo. Añade las cebollas cortadas en juliana fina y la miel (o el sirope sin azúcar). Cocina lentamente, removiendo ocasionalmente, durante 20-30 minutos hasta que estén bien caramelizadas, tiernas y doradas.\"},{\"step\":3,\"image_url\":null,\"description\":\"Retira las cebollas de la sartén y resérvalas. En la misma sartén, añade otra cucharada de aceite de oliva y sube el fuego a medio-alto. Sella el pollo por todos los lados hasta que esté dorado.\"},{\"step\":4,\"image_url\":null,\"description\":\"Reduce el fuego a medio. Agrega el ajo picado y cocina por 1 minuto hasta que esté fragante. Vierte el caldo de pollo para desglasar la sartén, raspando cualquier trozo pegado del fondo para incorporar todo el sabor.\"},{\"step\":5,\"image_url\":null,\"description\":\"Incorpora la crema de leche y las cebollas caramelizadas reservadas a la sartén. Deja que la salsa hierva a fuego lento durante unos 5-7 minutos, o hasta que espese ligeramente y el pollo esté completamente cocido.\"},{\"step\":6,\"image_url\":null,\"description\":\"Sirve el pollo inmediatamente, cubierto con la abundante salsa de cebolla caramelizada. Espolvorea con perejil fresco picado antes de servir, si lo deseas.\"}]','{\"text\":\"Para unas cebollas caramelizadas perfectas, cocínalas a fuego muy bajo y con paciencia, removiendo ocasionalmente para que no se quemen y desarrollen un dulzor profundo. Si deseas una versión más ligera, puedes omitir la crema de leche y la receta quedará igualmente deliciosa y con un sabor intenso a cebolla caramelizada. Además, recuerda que puedes sustituir la miel por cualquier sirope sin azúcar para ajustar el dulzor o adaptarlo a dietas específicas.\",\"url\":\"https://www.tiktok.com/@oskarinalanza/video/7564158261310672149?is_from_webapp=1&sender_device=pc&web_id=7579603530803611158\"}',0),
('1780090592076','Pollo al limón estilo chino','/uploads/53wb15qs6ha_1780374052913.jpeg','[\"Pollo\"]','standard','50 min ',NULL,0,0,NULL,NULL,NULL,'1780743065787','[\"1780743065787\",\"comida\"]','[{\"cantidad\":\"1\",\"ingrediente\":\"Pechuga de pollo (cortada a la mitad)\"},{\"cantidad\":\"50ml\",\"ingrediente\":\"Salsa de soja (con sal)\"},{\"cantidad\":\"1\",\"ingrediente\":\"Huevo\"},{\"cantidad\":\"2 cucharadas soperas\",\"ingrediente\":\"Maizena (para rebozar)\"},{\"cantidad\":\"Abundante\",\"ingrediente\":\"Aceite de oliva para freír\"},{\"cantidad\":\"Zumo de 1\",\"ingrediente\":\"Limón (para la salsa)\"},{\"cantidad\":\"4\",\"ingrediente\":\"Rodajas de limón\"},{\"cantidad\":\"250ml\",\"ingrediente\":\"Caldo de pollo\"},{\"cantidad\":\"1 cuchara sopera\",\"ingrediente\":\"Maizena (para la salsa)\"},{\"cantidad\":\"2 cucharadas soperas (40g)\",\"ingrediente\":\"Azúcar\"},{\"cantidad\":\"1/2 cucharada\",\"ingrediente\":\"Salsa de soja (opcional, para la salsa)\"}]','[{\"step\":1,\"image_url\":null,\"description\":\"Limpia la pechuga de pollo, córtala por la mitad y marínala en la salsa de soja durante 30 minutos en el refrigerador.\"},{\"step\":2,\"image_url\":null,\"description\":\"Para la salsa de limón, mezcla el zumo de limón, el caldo de pollo, la maizena y el azúcar en una sartén. Calienta a fuego medio junto con las rodajas de limón. Cocina hasta que hierva y espese. Si es necesario, aligera con un poco más de caldo. Reserva la salsa.\"},{\"step\":3,\"image_url\":null,\"description\":\"Retira el pollo de la marinada y sécalo bien con papel absorbente. En un recipiente aparte, bate el huevo con la maizena hasta obtener una mezcla homogénea y reboza el pollo con esta preparación.\"},{\"step\":4,\"image_url\":null,\"description\":\"En una sartén con abundante aceite caliente, fríe el pollo rebozado a fuego medio durante un par de minutos por cada lado, o hasta que esté dorado y cocido. Esto evitará que se queme. Pásalo a papel absorbente para eliminar el exceso de grasa. Luego, porciónalo, emplátalo, riega generosamente con la salsa de limón y decora con las rodajas de limón. ¡Disfruta!\"}]','{\"text\":\"Para un pollo perfectamente crujiente y dorado, asegúrate de que el aceite esté bien caliente a fuego medio antes de freír, y evita sobrecargar la sartén para mantener una temperatura uniforme. Además, puedes ajustar la consistencia de la salsa de limón: si la prefieres más ligera, añade un poco más de caldo; si la quieres más espesa, disuelve un poco más de maizena en agua fría y agrégala mientras calientas.\",\"url\":\"https://www.tiktok.com/@poesiadefogon/video/7202331757163662597?is_from_webapp=1&sender_device=pc&web_id=7579603530803611158\"}',0),
('1780090769977','Fajita aguacate para desayuno','/uploads/rsgzxcnzs8i_1780150530042.jpeg','[\"tostada\",\"aguacate\",\"desayuno\"]','standard','5 min',NULL,0,0,NULL,NULL,NULL,NULL,'[]','[{\"cantidad\":\"2\",\"ingrediente\":\"huevos\"},{\"cantidad\":\"Al gusto\",\"ingrediente\":\"Pimienta negra y sal\"},{\"cantidad\":\"1\",\"ingrediente\":\"fajita\"},{\"cantidad\":\"Al gusto\",\"ingrediente\":\"Espinacas baby\"},{\"cantidad\":\"Al gusto\",\"ingrediente\":\"Queso feta\"},{\"cantidad\":\"Al gusto\",\"ingrediente\":\"Aguacate\"},{\"cantidad\":\"1/2\",\"ingrediente\":\"Tomate\"}]','[{\"step\":1,\"image_url\":null,\"description\":\"Bate los dos huevos en un bol y sazona con pimienta negra y sal al gusto.\"},{\"step\":2,\"image_url\":null,\"description\":\"Calienta una sartén antiadherente a fuego medio y cocina los huevos batidos hasta que estén cocidos a tu gusto, como una tortilla o huevos revueltos.\"},{\"step\":3,\"image_url\":null,\"description\":\"Mientras se cocinan los huevos, calienta ligeramente la fajita en la misma sartén o en el microondas para que sea más flexible.\"},{\"step\":4,\"image_url\":null,\"description\":\"Coloca los huevos cocidos sobre la fajita caliente. Añade las espinacas baby, el queso feta desmenuzado y unas rodajas de aguacate.\"},{\"step\":5,\"image_url\":null,\"description\":\"Enrolla o dobla la fajita por la mitad y sirve inmediatamente para disfrutar de este desayuno rápido y saludable.\"}]','{\"text\":\"Para asegurar que los huevos queden jugosos y no secos, retíralos del fuego justo cuando hayan cuajado pero aún conserven un poco de humedad. Puedes añadir unas gotas de tu salsa picante favorita para un toque extra.\",\"url\":\"https://www.tiktok.com/@marioortiznutricion/video/7286071804005764385?is_from_webapp=1&sender_device=pc&web_id=7579603530803611158\"}',0),
('1780091430817','Tosta Gourmet de Salmón y Burrata con Pesto Casero','/uploads/5s402w0g99t_1780150794219.jpeg','[\"Desayuno\",\"tostada\",\"salmon\"]','standard','10 min ',NULL,0,0,NULL,NULL,NULL,NULL,'[]','[{\"cantidad\":\"1 rebanada\",\"ingrediente\":\"pan integral\"},{\"cantidad\":\"2 CS\",\"ingrediente\":\"pesto casero\"},{\"cantidad\":\"1/2\",\"ingrediente\":\"burrata\"},{\"cantidad\":\"40-50 gr\",\"ingrediente\":\"salmón ahumado\"},{\"cantidad\":\"1/2 CP\",\"ingrediente\":\"sésamo negro\"},{\"cantidad\":\"4-5\",\"ingrediente\":\"almendras picadas\"},{\"cantidad\":\"4 tazas\",\"ingrediente\":\"albahaca fresca (para el pesto)\"},{\"cantidad\":\"3/4 taza\",\"ingrediente\":\"aceite de oliva (para el pesto)\"},{\"cantidad\":\"1/2 taza\",\"ingrediente\":\"queso parmesano (para el pesto)\"},{\"cantidad\":\"2 dientes\",\"ingrediente\":\"ajo (para el pesto)\"},{\"cantidad\":\"1/4 taza\",\"ingrediente\":\"almendras (para el pesto, tradicionalmente piñones)\"},{\"cantidad\":\"1/2 cucharada\",\"ingrediente\":\"vinagre blanco (para el pesto)\"},{\"cantidad\":\"1/2 CP\",\"ingrediente\":\"sal (para el pesto)\"},{\"cantidad\":\"Al gusto\",\"ingrediente\":\"pimienta (para el pesto)\"}]','[{\"step\":1,\"image_url\":null,\"description\":\"Si vas a preparar el pesto casero, lava y seca bien las hojas de albahaca, asegurándote de usar solo las hojas para evitar amargura. En un procesador de alimentos, combina las hojas de albahaca, el aceite de oliva, el queso parmesano, los dientes de ajo, las almendras (o piñones), el vinagre blanco, la sal y la pimienta. Tritura hasta obtener una salsa homogénea y con la consistencia deseada.\"},{\"step\":2,\"image_url\":null,\"description\":\"Tuesta la rebanada de pan integral hasta que esté dorada y crujiente a tu gusto.\"},{\"step\":3,\"image_url\":null,\"description\":\"Extiende las 2 cucharadas de pesto casero (o comprado) sobre el pan tostado.\"},{\"step\":4,\"image_url\":null,\"description\":\"Coloca la media burrata sobre el pesto.\"},{\"step\":5,\"image_url\":null,\"description\":\"Distribuye el salmón ahumado sobre la burrata.\"},{\"step\":6,\"image_url\":null,\"description\":\"Espolvorea con el sésamo negro y las almendras picadas.\"},{\"step\":7,\"image_url\":null,\"description\":\"Sirve inmediatamente y, si lo deseas, acompaña con una ensalada.\"}]','{\"text\":\"Para el pesto casero, recuerda usar SÓLO las hojas de albahaca para evitar un sabor amargo, y el vinagre blanco no solo le da un toque especial, sino que también ayuda a su conservación natural. Almacena cualquier pesto sobrante en un recipiente de vidrio hermético en la nevera para que se mantenga fresco por más tiempo. Si buscas una alternativa más ligera o no tienes pesto, puedes sustituirlo por tomate natural rallado con un poco de ajo, que también queda delicioso. Esta tosta es perfecta para una cena rápida y deliciosa; para completarla, te sugiero acompañarla de una ensalada fresca.\",\"url\":\"https://www.tiktok.com/@lacadenasaludable/video/7206017915231980806?is_from_webapp=1&sender_device=pc&web_id=7579603530803611158\"}',0),
('1780091576567','Tortilla Proteica para el Desayuno','/uploads/1q59yjrrvqr_1780568085586.png','[\"tortitas\",\"aguacate\"]','standard','15 minutos',NULL,0,0,NULL,NULL,NULL,NULL,'[]','[{\"cantidad\":\"1/2\",\"ingrediente\":\"Tomate\"},{\"cantidad\":\"4\",\"ingrediente\":\"Huevos\"},{\"cantidad\":\"2 Láminas\",\"ingrediente\":\"Queso mantecoso\"},{\"cantidad\":\"2 Láminas\",\"ingrediente\":\"Jamón de pavo\"},{\"cantidad\":\"1/2 Mediana\",\"ingrediente\":\"Palta\"},{\"cantidad\":\"1\",\"ingrediente\":\"Tortilla XL Pancho Villa\"},{\"cantidad\":\"Al gusto\",\"ingrediente\":\"Sal\"},{\"cantidad\":\"Al gusto\",\"ingrediente\":\"Pimienta\"},{\"cantidad\":\"Un chorrito\",\"ingrediente\":\"Aceite de oliva o mantequilla\"}]','[{\"step\":1,\"image_url\":null,\"description\":\"Prepara tus ingredientes: Pica el tomate y la palta en dados pequeños. Si el jamón y el queso no están ya en láminas, córtalos.\"},{\"step\":2,\"image_url\":null,\"description\":\"En un bol, bate los 4 huevos enérgicamente con sal y pimienta al gusto hasta que estén bien mezclados.\"},{\"step\":3,\"image_url\":null,\"description\":\"Calienta una sartén antiadherente a fuego medio con un chorrito de aceite de oliva o mantequilla. Vierte los huevos batidos y cocina, removiendo suavemente si prefieres huevos revueltos, o dejando que cuaje si buscas una tortilla tipo omelet. Cocina hasta que los huevos estén a tu gusto.\"},{\"step\":4,\"image_url\":null,\"description\":\"Mientras los huevos se cocinan, calienta la Tortilla XL Pancho Villa. Puedes hacerlo en una sartén seca por unos segundos por cada lado, en el microondas o según las instrucciones del paquete para que esté suave y flexible.\"},{\"step\":5,\"image_url\":null,\"description\":\"Una vez caliente, coloca la tortilla Pancho Villa en un plato. Distribuye los huevos cocidos sobre una mitad de la tortilla.\"},{\"step\":6,\"image_url\":null,\"description\":\"Encima de los huevos, añade las láminas de queso mantecoso y jamón de pavo. Luego, incorpora el tomate y la palta picados.\"},{\"step\":7,\"image_url\":null,\"description\":\"Enrolla o dobla cuidadosamente la tortilla Pancho Villa para formar un burrito o un wrap. Sirve tu desayuno proteico inmediatamente.\"}]','{\"text\":\"Para un toque extra de sabor y una mayor densidad nutricional, considera añadir un puñado de espinacas frescas o champiñones salteados junto a los huevos. Unas gotas de tu salsa picante favorita o hierbas frescas como el cilantro picado también pueden realzar el plato.\",\"url\":\"https://vm.tiktok.com/ZNRWgGDYQ/\"}',0),
('1780130792360','Coliflor Gratinada','/uploads/fd0o4q4tcg_1780150607465.jpeg','[\"Mediterránea\",\"SinGluten\"]','standard','45-60 min',NULL,0,0,NULL,NULL,NULL,NULL,'[]','[{\"cantidad\":\"1\",\"ingrediente\":\"Coliflor\"},{\"cantidad\":\"1/2\",\"ingrediente\":\"Cebolla\"},{\"cantidad\":\"3\",\"ingrediente\":\"Dientes de ajo\"},{\"cantidad\":\"35g\",\"ingrediente\":\"Mantequilla\"},{\"cantidad\":\"35g\",\"ingrediente\":\"Harina\"},{\"cantidad\":\"600ml\",\"ingrediente\":\"Leche entera\"},{\"cantidad\":\"150g\",\"ingrediente\":\"Panceta curada\"},{\"cantidad\":\"150g\",\"ingrediente\":\"Mozzarella rallada\"},{\"cantidad\":\"Al gusto\",\"ingrediente\":\"Sal\"},{\"cantidad\":\"Al gusto\",\"ingrediente\":\"Pimienta\"},{\"cantidad\":\"Al gusto (opcional)\",\"ingrediente\":\"Nuez moscada\"},{\"cantidad\":\"Un chorro\",\"ingrediente\":\"Aceite de oliva\"}]','[{\"step\":1,\"image_url\":null,\"description\":\"Empieza limpiando la coliflor: retira las hojas y el tallo, luego separa los floretes. Hierve la coliflor en abundante agua con sal durante 10-15 minutos, hasta que esté tierna pero firme y no se deshaga.\"},{\"step\":2,\"image_url\":null,\"description\":\"Mientras, sofríe la cebolla y el ajo finamente picados en una cazuela con un chorro de aceite a fuego suave hasta que cambien de color. En la misma cazuela, funde la mantequilla, incorpora la harina y cocina a fuego medio por un par de minutos para eliminar el sabor a crudo de la harina, evitando que se tueste.\"},{\"step\":3,\"image_url\":null,\"description\":\"Agrega la mitad de la leche templada o caliente y remueve constantemente con varillas a fuego medio-alto hasta que comience a espesar. Vierte el resto de la leche y repite el proceso. Cuando la bechamel haya espesado ligeramente, salpimenta al gusto. Hierve por un par de minutos a fuego suave y estará lista. Si queda demasiado espesa, agrega un poco más de leche caliente e integra bien.\"},{\"step\":4,\"image_url\":null,\"description\":\"En otra sartén, dora la panceta curada hasta que esté crujiente. Retira a papel absorbente para eliminar el exceso de grasa.\"},{\"step\":5,\"image_url\":null,\"description\":\"En una bandeja de horno, extiende una capa de bechamel como base. Coloca encima la coliflor cocida, el bacon crujiente y napa todo con el resto de la bechamel. Cubre generosamente con la mozzarella rallada.\"},{\"step\":6,\"image_url\":null,\"description\":\"Cocina en horno precalentado a 220ºC, a media altura y con calor arriba y abajo (sin ventilación), durante 10 minutos aproximadamente, hasta que la bechamel burbujee y el queso se funda. Finaliza gratinando con la función de grill por 5 minutos, o hasta que el queso esté bien dorado.\"}]','{\"text\":\"Para una bechamel perfecta, asegúrate de cocinar la harina con la mantequilla por un par de minutos para eliminar el sabor a crudo, pero sin que se tueste. Si la bechamel queda demasiado espesa, no dudes en añadir un poco más de leche caliente y mezclar bien hasta obtener la consistencia deseada. El truco es mantener la suavidad.\",\"url\":\"https://www.tiktok.com/@poesiadefogon/video/7608266764665015574?is_from_webapp=1&sender_device=pc&web_id=7552083830309766678\"}',0),
('1780150151982','Pizza fresca','/uploads/1cxtd9cf4du_1780150150757.jpeg','[\"Pizza\",\"cena\"]','standard','30 min',NULL,0,0,NULL,NULL,NULL,'1780741843239','[\"1780741843239\"]','[{\"cantidad\":\"1\",\"ingrediente\":\"Pizza fresca mercadona\"},{\"cantidad\":\"2 cuch\",\"ingrediente\":\"Salsa de yogurt\"},{\"cantidad\":\"4 lonchas\",\"ingrediente\":\"Jamón serrana\"}]','[]','{\"text\":\"\",\"url\":\"\"}',0),
('1780150423443','Hamburguesa','/uploads/niltrdmlcg_1780150422030.jpeg','[\"Hamburguesa\",\"cena\"]','standard','30 min',NULL,0,0,NULL,NULL,NULL,'4','[\"4\"]','[{\"cantidad\":\"2\",\"ingrediente\":\"Pan de hamburguesa\"},{\"cantidad\":\"2\",\"ingrediente\":\"Hamburguesas\"},{\"cantidad\":\"2 lonchas\",\"ingrediente\":\"Queso\"},{\"cantidad\":\"1/4\",\"ingrediente\":\"Cebolla\"},{\"cantidad\":\"4\",\"ingrediente\":\"Pepinillos\"}]','[]','{\"text\":\"\",\"url\":\"\"}',0),
('1780258535161','No-nutela','/uploads/rvxwsmpw9y_1780258534127.jpeg','[\"No-Nutela\",\"Postres\",\"Dulces\"]','standard','15 min',NULL,0,0,NULL,NULL,NULL,'5','[\"5\"]','[{\"cantidad\":\"120 gr\",\"ingrediente\":\"Dátiles sin hueso\"},{\"cantidad\":\"100 gr\",\"ingrediente\":\"Aguacate\"},{\"cantidad\":\"100 gr\",\"ingrediente\":\"Leche desnatada\"},{\"cantidad\":\"40 gr\",\"ingrediente\":\"Caco puro en polvo\"},{\"cantidad\":\"Al gusto\",\"ingrediente\":\"Nueces o avellanas\"}]','[{\"step\":1,\"image_url\":null,\"description\":\"Hidrata los dátiles 10 minutos en agua caliente. Pasado ese tiempo, escúrrelos bien\"},{\"step\":2,\"image_url\":null,\"description\":\"Introduce todos los ingredientes en el vaso de la trituradora, y tritúralo hasta que quede una pasta de consistencia cremosa\"},{\"step\":3,\"image_url\":null,\"description\":\"Guardar en un recipiente hermético\"}]','{\"text\":\"\",\"url\":\"\"}',0),
