('1780374164878','Crema de calabaza','/uploads/my1p00klypi_1780374161162.jpeg','[\"Crema\",\"calabaza\",\"zanahoria\"]','standard','30 min',NULL,0,0,NULL,NULL,NULL,'1780741830059','[\"1780741830059\"]','[{\"cantidad\":\"400 gr\",\"ingrediente\":\"Calabaza\"},{\"cantidad\":\"1\",\"ingrediente\":\"Patata mediana\"},{\"cantidad\":\"2\",\"ingrediente\":\"Zanahorias\"},{\"cantidad\":\"30 ml\",\"ingrediente\":\"AOVE\"},{\"cantidad\":\"1 cucharadita\",\"ingrediente\":\"Sal\"},{\"cantidad\":\"650 gr\",\"ingrediente\":\"Agua\"},{\"cantidad\":\"1\",\"ingrediente\":\"Puerro\"}]','[{\"step\":1,\"image_url\":null,\"description\":\"Introducimos el puerro en el vaso picador y lo picamos. Sofreímos a fuego lento unos 8 minutos\"}]','{\"text\":\"\",\"url\":\"\"}',0),
