('1780659606463','Mojo picón ','/uploads/xw7qm4q67wc_1780659605086.jpeg','[\"Salsas\",\"Mojo\"]','standard','15 min',NULL,0,0,NULL,NULL,NULL,'1780743016938','[\"1780743016938\"]','[{\"cantidad\":\"1\",\"ingrediente\":\"Huevo crudo\"},{\"cantidad\":\"1 \",\"ingrediente\":\"Vaso de aceite de girasol sin llenar\"},{\"cantidad\":\"2\",\"ingrediente\":\"Ajo\"},{\"cantidad\":\"1,5 cucharada\",\"ingrediente\":\"Pimentón dulce/picante\"},{\"cantidad\":\"1 chorro\",\"ingrediente\":\"Vinagre\"},{\"cantidad\":\"1/2 cucharadita\",\"ingrediente\":\"Sal\"},{\"cantidad\":\"1 cucharadita\",\"ingrediente\":\"Orégano \"},{\"cantidad\":\"1 cucharadita\",\"ingrediente\":\"Comino\"},{\"cantidad\":\"1/2\",\"ingrediente\":\"Guindilla (cayena) pequeña\"},{\"cantidad\":\"3 cucharadas\",\"ingrediente\":\"Tomate crudo de bote\"}]','[{\"step\":1,\"image_url\":null,\"description\":\"Todo batido con la batidora, empezando desde abajo\"}]','{\"text\":\"\",\"url\":\"\"}',0),
